(function(root){'use strict';const base=root.PaisGuide,records=[{"jobId":"OP-20261110N-pps_catalog_ececdc23fb19e7b9","ageSections":{},"key":"pps_catalog_ececdc23fb19e7b9","label":"Fascite necrosante — registro no PPS","specific":true,"entity":"Fascite necrosante","assessment":"{\"classification\":\"Variante ortográfica da mesma doença pediátrica\",\"assessment\":\"ID próprio. Equivalência com grafia Fasciíte necrosante. pdf1500_649 é ficha publicada; não substituir o ID nem contar nova doença. Rótulos de gravidade ou evolução não permitem presumir que a criança tem choque ou falhou antibiótico; a suspeita da doença já justifica emergência.\"}","sections":{"CUIDADOS EM CASA":["Fascite necrosante é uma infecção profunda que pode avançar em poucas horas sob uma pele ainda pouco alterada. Se há suspeita agora, leve a criança imediatamente ao pronto-socorro. Não espere febre, pus, bolhas ou a pele escurecer. Se já está no hospital, avise a equipe agora.","Pode começar depois de um corte, cirurgia, batida ou catapora, mas nem sempre há ferida evidente. Conte à equipe quando começaram a dor e o inchaço e se a área aumentou desde então."],"MEDIDAS SEM REMÉDIOS":["Não fure, esprema nem tente retirar o tecido da ferida. Não atrase a ida para passar pomada, fazer compressa ou marcar o contorno para observar a evolução.","Depois da alta, lave as mãos antes e depois dos cuidados. Siga o plano da cirurgia para os curativos e para voltar a movimentar ou apoiar a região; isso depende da extensão da lesão."],"MEDICAMENTOS":["A equipe cirúrgica precisa avaliar a criança imediatamente. Se a infecção for confirmada, o tratamento inclui antibióticos pela veia e cirurgia para retirar o tecido infectado; às vezes é preciso operar de novo. Um antibiótico oral usado para infecção de pele simples não substitui esse atendimento.","Se já recebeu alta, use os medicamentos conforme a receita e telefone à equipe se não conseguir administrá-los. Não use sobras nem ofereça antibiótico a familiares por conta própria."],"ALIMENTAÇÃO E LÍQUIDOS":["Não atrase a saída para dar uma refeição ou mamada. Informe à equipe quando a criança comeu ou bebeu pela última vez, pois pode precisar de cirurgia. Se estiver sonolenta, difícil de acordar ou engasgando, não ofereça nada pela boca.","Após cirurgia, retome leite, líquidos ou refeições apenas conforme a equipe liberar. Se voltou a vomitar ou não consegue beber depois da alta, peça orientação à equipe no mesmo dia; se estiver abatida ou piorando rapidamente, vá ao pronto-socorro."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Dor intensa maior do que a aparência da pele faz supor, inchaço que cresce depressa ou dor que se estende além da parte vermelha exigem atendimento imediato. Pele arroxeada, bolhas ou perda de sensibilidade também são alarmes, mas podem aparecer só mais tarde.","Se a criança ficar muito mole, difícil de acordar, com respiração anormal, muito pálida ou desmaiar, ligue para o SAMU (192). Não espere aparecerem vários sinais ao mesmo tempo."],"QUANDO REAVALIAR":["Na suspeita ativa, o retorno é agora, mesmo que uma consulta anterior tenha sugerido infecção de pele simples. Não espere o dia seguinte nem o resultado de um exame ambulatorial.","Depois da alta, confirme por escrito quando a cirurgia vai rever a ferida e quem fará os próximos curativos. Se não recebeu o plano, contate o serviço que deu a alta. Dor novamente intensa ou vermelhidão e inchaço que voltam a avançar exigem pronto-socorro, sem esperar o retorno marcado."]},"ageMap":{"u3m":"O bebê não consegue indicar a dor. Inchaço novo em rápida progressão ou choro intenso ao tocar a área requer pronto-socorro. Bebê difícil de acordar ou com respiração anormal precisa de socorro imediato, mesmo sem febre.","3a5m":"Se o bebê deixou de mexer um braço ou uma perna e chora ao ser manuseado, conte isso à equipe. Não aperte a região para testar a dor.","6a11m":"Observe se passou a proteger uma região ou a evitar movimentos que fazia normalmente. Não espere uma bolha se abrir para procurar ajuda.","1a":"Se parou de apoiar a perna ou chora quando a roupa encosta no local dolorido e o inchaço está aumentando, leve-o à emergência sem fazê-lo andar.","2a5":"Após catapora, dor muito forte em uma região ou inchaço que piora depressa não deve ser atribuído apenas às bolhas. Procure avaliação imediatamente.","6a11":"Pergunte à criança onde dói, inclusive além da área que parece vermelha. Não peça que corra ou mova o membro para testar e não espere o fim da aula.","12a17":"Depois de pancada em treino ou de uma cirurgia, dor muito intensa que piora depressa exige avaliação mesmo que não haja corte visível. Não treine para ver se a dor passa.","unknown":"Informe idade, local e hora aproximada do início da dor ou do inchaço. Não espere conseguir fotos ou todos os detalhes para buscar socorro."},"refs":[{"id":"pais20261110_batchN_pps_catalog_ececdc23fb19e7b9_1","name":"Cellulitis and other bacterial skin infections","url":"https://www.rch.org.au/clinicalguide/guideline_index/Cellulitis_and_Skin_Infections/"},{"id":"pais20261110_batchN_pps_catalog_ececdc23fb19e7b9_2","name":"Clinical Guidance for Type II Necrotizing Fasciitis","url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/necrotizing-fasciitis.html"},{"id":"pais20261110_batchN_pps_catalog_ececdc23fb19e7b9_3","name":"About Necrotizing Fasciitis","url":"https://www.cdc.gov/group-a-strep/about/necrotizing-fasciitis.html"},{"id":"pais20261110_batchN_pps_catalog_ececdc23fb19e7b9_4","name":"Serviço de Atendimento Móvel de Urgência (SAMU 192)","url":"https://www.gov.br/saude/pt-br/composicao/saes/samu-192"},{"id":"pais20261110_batchN_pps_catalog_ececdc23fb19e7b9_5","name":"Skin and Soft-Tissue Infections","url":"https://idmp.ucsf.edu/guidelines-empiric-therapy-categories/skin-and-soft-tissue-infections"}],"aliases":["Fascite necrosante — apresentação pediátrica aguda","Fascite necrosante — evolução complicada/refratária","Fascite necrosante — forma grave/crítica"],"alwaysUrgent":true,"urgentAges":[],"urgentAcute":false,"resultPath":"references/orientacoes-validadas/parallel-results/OP-20261110N-pps_catalog_ececdc23fb19e7b9.json","resultHash":"863bbdad5a725161d675cf72be112279875c2ccfdd4e3f11a4d647ccd7094966"},{"jobId":"OP-20261110N-pps_catalog_7d4ab836051709f7","ageSections":{},"key":"pps_catalog_7d4ab836051709f7","label":"Fibrilação atrial de alta resposta ventricular — registro no PPS","specific":true,"entity":"Fibrilação atrial com resposta ventricular rápida","assessment":"\"Arritmia atrial com qualificador de frequência ventricular, não fibrilação ventricular nem diagnóstico de parada. FA paroxística descreve padrão temporal e não necessariamente resposta rápida. Preservar pps_catalog_8ffc711ac26d93cf e pps_catalog_288cc345dab9d8e5 separados. Não criar alias simples FA.\"","sections":{"CUIDADOS EM CASA":["Se a criança está com fibrilação atrial rápida agora ou se o coração voltou a bater muito depressa e irregularmente em repouso, procure pronto atendimento agora, mesmo que ela consiga conversar. Não espere a próxima consulta para fazer o eletrocardiograma.","Nesse ritmo, os sinais elétricos da parte de cima do coração ficam desorganizados e a parte de baixo bate depressa demais. Isso pode prejudicar a circulação. Não é o mesmo que parada cardíaca: não faça compressões em uma criança acordada ou respirando normalmente."],"MEDIDAS SEM REMÉDIOS":["Interrompa o esforço, deixe a criança descansar na posição em que respira melhor e fique com ela. Se puder, anote quando começou e leve os exames anteriores e a lista de remédios. Não atrase a saída para contar os batimentos, filmar ou obter uma leitura do relógio.","Não aperte o pescoço ou os olhos nem tente mergulhar o rosto da criança em água gelada para interromper esse ritmo."],"MEDICAMENTOS":["Não dê uma dose extra de remédio para desacelerar o coração. Remédios que servem para um tipo de arritmia podem ser perigosos em outro. Não comece aspirina nem anticoagulante por conta própria. Após a alta, siga apenas a prescrição e o plano escrito da cardiologia."],"ALIMENTAÇÃO E LÍQUIDOS":["Água, bebidas açucaradas e comida não corrigem a arritmia. Se houver falta de ar importante, desmaio ou dificuldade para despertar, não dê nada pela boca. Depois de estabilizar, siga as orientações da equipe para voltar a mamar ou comer."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Ligue para o SAMU (192) agora se houver desmaio, dificuldade importante para respirar, dor forte no peito, palidez intensa com suor frio ou dificuldade para acordar. No bebê, observe se fica mole, muito pálido ou sem fôlego para mamar.","Se não responder e não respirar normalmente (ou só der suspiros), peça ajuda e um desfibrilador automático, ligue 192 no viva-voz e comece as compressões no centro do peito seguindo o atendente. Não procure pulso nem espere o aparelho para começar."],"QUANDO REAVALIAR":["Se um primeiro episódio passou antes de chegar ao atendimento, procure avaliação ainda hoje; informe o horário de início e de melhora. Se volta a acelerar ou surge um sinal de alarme, não espere. Se já houve alta e a criança está bem, mantenha o retorno combinado com a cardiologia pediátrica para investigar a causa, a possibilidade de repetição e a segurança para retomar esportes."]},"ageMap":{"u3m":"No bebê pequeno a alteração pode se mostrar só como dificuldade repentina para mamar ou pouca reação ao toque. Se estiver mole, muito pálido ou respirando com esforço, acione o SAMU.","3a5m":"Se o bebê pausa a mamada repetidamente para respirar e parece abatido, não force a mamada. Observe a respiração e procure atendimento.","6a11m":"Um bebê ainda não consegue contar que sente palpitações. Diga à equipe se ficou muito quieto, pálido ou cansado de repente e se isso ocorreu durante a mamada ou em repouso.","1a":"Se a criança para de brincar de repente, fica pálida e com respiração difícil durante os batimentos rápidos, não a coloque para caminhar; chame o SAMU.","2a5":"A criança pode apontar para o peito sem conseguir explicar o que sente. Observe se ficou sem fôlego ou cambaleou e diga quando isso começou.","6a11":"Pergunte se sente o peito batendo depressa ou aos pulos e se houve tontura; avise à escola quem deve ser chamado se os sintomas voltarem. Não peça que corra para testar o coração.","12a17":"Se os sintomas começaram no treino, interrompa a atividade. Mesmo que melhorem em repouso, conte à equipe se houve dor no peito ou desmaio e não volte ao esporte antes de receber orientação.","unknown":"Não é preciso conhecer a idade exata nem saber a frequência do pulso para pedir ajuda quando a criança está muito pálida, desmaia ou respira com dificuldade."},"refs":[{"id":"pais20261110_batchN_pps_catalog_7d4ab836051709f7_1","name":"Atrial Fibrillation in Children","url":"https://www.stroke.org/en/health-topics/atrial-fibrillation/who-is-at-risk-for-atrial-fibrillation-af-or-afib/atrial-fibrillation-in-children"},{"id":"pais20261110_batchN_pps_catalog_7d4ab836051709f7_2","name":"Protocolos de Suporte Avançado de Vida — SAMU 192","url":"https://bvsms.saude.gov.br/bvs/publicacoes/protocolo_suporte_avancado_vida.pdf"},{"id":"pais20261110_batchN_pps_catalog_7d4ab836051709f7_3","name":"Part 8: Pediatric Advanced Life Support","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/pediatric-advanced-life-support"},{"id":"pais20261110_batchN_pps_catalog_7d4ab836051709f7_4","name":"Diagnosis and management of very rare primary arrhythmia syndromes in children and adults","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13522997/"},{"id":"pais20261110_batchN_pps_catalog_7d4ab836051709f7_5","name":"Arrhythmia","url":"https://www.childrens.health.qld.gov.au/health-a-to-z/cardiac/arrhythmia"},{"id":"pais20261110_batchN_pps_catalog_7d4ab836051709f7_6","name":"Part 6: Pediatric Basic Life Support","url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/pediatric-basic-life-support"}],"aliases":["Fibrilação atrial de alta resposta ventricular","Fibrilação atrial de alta resposta ventricular — apresentação pediátrica aguda","Fibrilação atrial de alta resposta ventricular — evolução complicada/refratária","Fibrilação atrial de alta resposta ventricular — forma grave/crítica"],"alwaysUrgent":true,"urgentAges":[],"urgentAcute":false,"resultPath":"references/orientacoes-validadas/parallel-results/OP-20261110N-pps_catalog_7d4ab836051709f7.json","resultHash":"0779ff31d60dd450708c0d245addb832b531d00b2b82bb31691204bc0e84d1df"},{"jobId":"OP-20261110N-pps_catalog_ec68c01a0c419fcd","ageSections":{},"key":"pps_catalog_ec68c01a0c419fcd","label":"Fácies assimétrica ao choro — registro no PPS","specific":true,"entity":"Assimetria congênita/neonatal do movimento do lábio inferior durante o choro","assessment":"{\"classification\":\"Fenótipo clínico neonatal válido, não diagnóstico etiológico específico\",\"distinctions\":\"Hipoplasia muscular ou compressão de ramo nervoso podem ter apresentação parecida. Não equiparar a paralisia de Bell, AVC, lesão traumática ou síndrome de Cayler/deleção 22q11.2 sem avaliação.\"}","sections":{"CUIDADOS EM CASA":["Quando um lado do lábio inferior desce menos ao chorar ou sorrir desde o nascimento, mas o rosto parece igual dos dois lados em repouso, o pediatra pode identificar uma assimetria do lábio. Os dois olhos costumam fechar normalmente. A aparência por si só não confirma a causa.","Quando o músculo do lábio se desenvolveu menos, a diferença pode persistir mesmo que fique menos evidente com o crescimento. Se começou de repente, não a trate como a mesma alteração de nascimento."],"MEDIDAS SEM REMÉDIOS":["Observe quando a diferença aparece e se desaparece ao relaxar. Não é preciso provocar o choro para testar. Se já tiver um vídeo espontâneo ou foto antiga, pode mostrá-lo na consulta."],"MEDICAMENTOS":["A diferença isolada no movimento do lábio não exige remédio em casa. Não comece medicamentos para paralisia facial por conta própria: uma fraqueza que acabou de surgir precisa de outro tipo de avaliação."],"ALIMENTAÇÃO E LÍQUIDOS":["Se a criança suga ou mastiga e engole normalmente, mantenha a alimentação habitual para a idade. Engasgos repetidos ou dificuldade para mamar não são explicados apenas pela aparência do lábio; peça avaliação no mesmo dia."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Se um lado do rosto ficar fraco de repente, ligue para o SAMU (192), mesmo que a criança já tenha uma diferença antiga no sorriso. Não espere aparecer fraqueza no braço ou na perna, fala enrolada ou convulsão para pedir socorro. Informe quando ela foi vista pela última vez como de costume.","Se o bebê ficar com a língua ou os lábios azulados, tiver muita dificuldade para respirar ou estiver difícil de acordar, ligue para o SAMU. Não force líquidos ou comida enquanto aguarda."],"QUANDO REAVALIAR":["Se notar o sinal na maternidade, mostre à equipe antes da alta. Se já estiver em casa e o achado for antigo, estável e ainda não avaliado, marque uma consulta com o pediatra. Ele examinará o rosto e o restante do corpo, inclusive o coração, e dirá se precisa de exames adicionais. Ter esse sinal não significa ter uma malformação cardíaca.","Se um olho não fecha por completo, procure avaliação no mesmo dia: isso não é típico da assimetria isolada do lábio. Se essa mudança foi súbita, siga a orientação de emergência. Após avaliação, se o padrão não mudou e a criança está bem, mantenha as consultas de rotina."]},"ageMap":{"u3m":"Se estiver na maternidade, mostre à equipe como o rosto fica em repouso e como o bebê mama. Se um olho fica aberto ao dormir, avise a equipe hoje.","3a5m":"Compare com o que já se via nas primeiras semanas. Se o bebê passou a soltar o peito ou a mamadeira repetidamente e não consegue mamar como antes, peça avaliação hoje.","6a11m":"Se a diferença antiga no sorriso é a única alteração, não é preciso mudar a textura das refeições só por causa do lábio. Relate se passou a engasgar.","1a":"Se notar o sorriso desigual agora, fotos antigas podem ajudar o pediatra a saber desde quando isso ocorre. Não atrase o socorro para procurá-las se a mudança foi repentina.","2a5":"Conte ao pediatra se a diferença aparece desde bebê só quando sorri ou faz careta. Se de repente ficar difícil falar ou movimentar um lado do rosto, chame o SAMU.","6a11":"Uma diferença antiga e estável no sorriso pode ser discutida na consulta, inclusive se a criança se sente constrangida. Fraqueza nova no rosto ou no braço exige socorro agora.","12a17":"Se o sorriso é diferente desde bebê, explique na consulta se isso incomoda ou interfere no dia a dia. Um sorriso que mudou subitamente não deve ser atribuído ao achado antigo.","unknown":"Informe a idade e se a diferença existe desde o nascimento. Se a fraqueza começou de repente, procure socorro agora."},"refs":[{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_1","name":"Neuro/Reflexes","url":"https://med.stanford.edu/newborns/professional-education/photo-gallery/neuro-reflexes.html"},{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_2","name":"Asymmetric crying facies in the newborn","url":"https://onlinelibrary.wiley.com/doi/10.1111/jpc.16337"},{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_3","name":"Asymmetric Crying Facies (CULLP)","url":"https://www.facialpalsy.org.uk/causesanddiagnoses/asymmetric-crying-facies/"},{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_4","name":"Pediatric Stroke","url":"https://www.chop.edu/conditions-diseases/pediatric-stroke"},{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_5","name":"Strokes in Children","url":"https://www.nationwidechildrens.org/conditions/strokes-in-children"},{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_6","name":"SAMU 192","url":"https://www.gov.br/saude/pt-br/composicao/saes/samu-192"},{"id":"pais20261110_batchN_pps_catalog_ec68c01a0c419fcd_7","name":"Asymmetric crying facies and associated congenital anomalies: prospective study and review of the literature","url":"https://journals.sagepub.com/doi/10.1177/088307380001501208"}],"aliases":["Fácies assimétrica ao choro"],"alwaysUrgent":false,"urgentAges":[],"urgentAcute":false,"resultPath":"references/orientacoes-validadas/parallel-results/OP-20261110N-pps_catalog_ec68c01a0c419fcd.json","resultHash":"4d51c0b2942624263d974bacb95fc4d48be580a79444374917be48a79d496719"},{"jobId":"OP-20261110N-pps_catalog_e26ac6f654a43600","ageSections":{},"key":"pps_catalog_e26ac6f654a43600","label":"Febre do Oropouche — registro no PPS","specific":true,"entity":"Doença aguda pelo vírus Oropouche","assessment":"\"Diagnóstico válido. O cadastro e seus qualificadores apontam à mesma arbovirose. Não confundir com dengue nem presumir infecção congênita por exposição materna.\"","sections":{"CUIDADOS EM CASA":["O Oropouche é uma infecção transmitida principalmente pela picada do maruim, também chamado mosquito-pólvora. Febre de início rápido, dor de cabeça e dores no corpo podem parecer dengue. Se a criança ainda não foi examinada, procure atendimento hoje; informe onde ela esteve e o dia em que começou a febre.","Após avaliação e liberação para casa, deixe-a descansar. Anote a febre, os vômitos, as mamadas ou líquidos aceitos e a quantidade de urina. Os sintomas podem voltar dias depois da melhora; não presuma que toda nova febre seja apenas uma recaída."],"MEDIDAS SEM REMÉDIOS":["Proteja a criança de novas picadas enquanto está doente. O maruim é pequeno: use telas ou mosquiteiro de malha fina e roupas leves que cubram braços e pernas. No quintal, retire folhas e frutas caídas.","Se usar repelente, escolha produto indicado no rótulo para a idade; não o passe nas mãos do bebê, perto da boca ou dos olhos. Para bebês que ainda não podem usar o produto, prefira a barreira de tecido ou tela."],"MEDICAMENTOS":["Não há antiviral específico. Use para dor ou febre somente o medicamento e a quantidade orientados pela equipe. Não dê aspirina (AAS) nem anti-inflamatórios, como ibuprofeno, por conta própria: há risco de sangramento, e a doença pode ser confundida com dengue."],"ALIMENTAÇÃO E LÍQUIDOS":["Mantenha as mamadas e, nas crianças maiores, ofereça líquidos em pequenos goles frequentes. Observe se consegue beber e urina como de costume. Se vomita tudo ou não consegue mamar, procure pronto atendimento; não insista em alimentar uma criança muito sonolenta."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Vá agora se houver dor de cabeça forte com rigidez no pescoço, confusão, dificuldade para acordar ou fraqueza nova. Em caso de convulsão, perda de consciência ou dificuldade importante para respirar, ligue 192.","Mesmo que a febre tenha baixado, dor forte e contínua na barriga, vômitos repetidos, desmaio ou sangramento pelo nariz ou gengivas exigem pronto atendimento. Esses sinais também podem ocorrer na dengue; não espere o resultado do exame."],"QUANDO REAVALIAR":["Após a alta, respeite o retorno marcado. Se a febre ou a dor de cabeça reaparecer após uma melhora, ou a criança estiver pior sem sinal de emergência, procure reavaliação no mesmo dia para verificar a causa. Com qualquer sinal de alarme, o retorno é imediato."]},"ageMap":{"u3m":"Em menores de 3 meses, febre de 38 °C ou mais exige pronto atendimento agora. Se a mãe teve Oropouche provável ou confirmado durante a gestação, avise a equipe da maternidade e o pediatra: o bebê precisa ser avaliado ao nascer e nas consultas de acompanhamento, mesmo se parecer bem. A exposição na gestação não confirma infecção no bebê.","3a5m":"Observe se o bebê acorda para mamar e se molha as fraldas como de costume. Continue o leite materno ou fórmula habitual; não substitua mamadas por água.","6a11m":"Ofereça mamadas frequentes. Menos fraldas molhadas, pouca resposta à voz e não conseguir manter líquidos são motivos para avaliação rápida.","1a":"Como ainda não consegue explicar se sente dor de cabeça, observe mudança na interação, choro muito diferente do habitual e irritabilidade persistente.","2a5":"Observe se a criança passa a evitar mexer o pescoço, fica sonolenta demais ou vomita repetidamente. Esses sinais pedem pronto atendimento.","6a11":"Se a criança disser que a cabeça voltou a doer depois de dias de melhora, anote o horário e procure reavaliação no mesmo dia. Pescoço duro ou confusão exigem pronto atendimento.","12a17":"Se a adolescente estiver grávida ou puder estar, avise a equipe no atendimento de hoje e o pré-natal. A infecção na gestação pode afetar o bebê e exige acompanhamento; isso não significa que o bebê esteja infectado.","unknown":"Informe a idade à equipe; conte sobre viagem, local de moradia e eventual contato com maruins. Não espere confirmar qual inseto picou para procurar atendimento."},"refs":[{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_1","name":"Oropouche","url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/o/oropouche"},{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_2","name":"Nota Técnica nº 13/2026/SEI/COVIG/GGPAF/DIRE5/ANVISA","url":"https://www.gov.br/anvisa/pt-br/assuntos/paf/vigilancia-epidemiologica/alertas-epidemiologicos/vigentes/nota-tecnica-no-13-2026-2013-arboviroses/@@download/file"},{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_3","name":"Clinical Overview of Oropouche Virus Disease","url":"https://www.cdc.gov/oropouche/hcp/clinical-overview/"},{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_4","name":"Interim Guidance for Evaluating and Managing Infants Born to Pregnant Women with Confirmed or Probable Oropouche Virus Disease","url":"https://www.cdc.gov/oropouche/hcp/clinical-care/infants.html"},{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_5","name":"Dengue: Quais são os sinais de alarme?","url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/dengue/faq/dengue/quais-sao-os-sinais-de"},{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_6","name":"When to get urgent medical help for babies and children under 5","url":"https://www.nhs.uk/baby/health/when-to-get-urgent-medical-help-for-babies-and-children-under-5/"},{"id":"pais20261110_batchN_pps_catalog_e26ac6f654a43600_7","name":"Produtos repelentes","url":"https://www.gov.br/anvisa/pt-br/comunicacao/campanhas/dengue/produtos-repelentes"}],"aliases":["Febre do Oropouche","Febre do Oropouche — apresentação pediátrica aguda","Febre do Oropouche — evolução complicada/refratária","Febre do Oropouche — forma grave/crítica"],"alwaysUrgent":false,"urgentAges":["u3m"],"urgentAcute":false,"resultPath":"references/orientacoes-validadas/parallel-results/OP-20261110N-pps_catalog_e26ac6f654a43600.json","resultHash":"413f427a67842e47d628ad571fcce53cbf12ff3787840adc7bc7205df929ceca"},{"jobId":"OP-20261110N-pps_catalog_a26ea1680821f3d8","ageSections":{},"key":"pps_catalog_a26ea1680821f3d8","label":"Fenilcetonúria — registro no PPS","specific":true,"entity":"Fenilcetonúria por deficiência da fenilalanina-hidroxilase","assessment":"{\"type\":\"Doença metabólica hereditária; registro no PPS é identificação administrativa.\",\"scope\":\"Fenilalanina alta na triagem pode ter outras causas; não equivale a doença confirmada nem define a necessidade ou a intensidade de restrição.\"}","sections":{"CUIDADOS EM CASA":["Se o teste do pezinho indicou possível fenilcetonúria ou fenilalanina alta, fale hoje com o serviço de triagem para combinar a confirmação. O bebê pode parecer bem. Não espere sintomas nem mude as mamadas por conta própria.","Na fenilcetonúria confirmada, o corpo tem dificuldade para processar a fenilalanina, uma parte das proteínas. Seu acúmulo prolongado pode prejudicar o desenvolvimento do cérebro. O tratamento iniciado cedo e mantido mesmo quando a criança está bem ajuda a prevenir esse dano."],"MEDIDAS SEM REMÉDIOS":["Deixe à mão o contato da equipe e o plano alimentar atualizado. Registre as coletas de sangue e as orientações recebidas; o exame, e não a presença de sintomas, mostra se o plano precisa mudar.","Combine com a escola ou creche quem prepara a alimentação e oferece a fórmula prescrita. Se perceber que ela vai acabar, procure o serviço antes de faltar; não a substitua por conta própria."],"MEDICAMENTOS":["Avise ao médico e ao farmacêutico que a criança tem fenilcetonúria. Alguns remédios adoçados contêm aspartame, que fornece fenilalanina; peça que confiram a apresentação. Não atrase um tratamento urgente por causa disso. Se a equipe metabólica prescreveu medicamento específico, use-o conforme o plano; não suspenda a dieta nem os exames por conta própria."],"ALIMENTAÇÃO E LÍQUIDOS":["Na doença confirmada, a dieta controla a quantidade de fenilalanina; não é uma dieta sem nenhuma proteína. Ofereça as porções e a fórmula metabólica indicadas para esta criança. Não troque a fórmula especial por suplemento de academia ou fórmula comum.","A amamentação pode continuar com orientação individual, combinada à fórmula metabólica quando indicada. Leia os rótulos para evitar o adoçante aspartame. Se a criança adoecer e estiver comendo ou mamando menos, avise a equipe para ajustar os cuidados; não retire alimentos nem dobre a fórmula por conta própria."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Procure pronto atendimento se os vômitos impedirem a criança de manter líquidos ou mamadas, sobretudo com pouca urina, ou se estiver muito sonolenta e difícil de acordar. Em caso de convulsão ou inconsciência, ligue para o SAMU (192). Não dê nada pela boca se não estiver bem acordada. Esses sinais não confirmam que a fenilalanina subiu; outras causas também precisam de avaliação."],"QUANDO REAVALIAR":["Se foi convocado após o teste do pezinho, cumpra o prazo da nova coleta mesmo que o bebê esteja mamando bem. Se não souber onde comparecer, procure o serviço que coletou o teste ainda hoje.","Depois do diagnóstico, mantenha as consultas e os exames nos intervalos definidos pelo serviço metabólico. Entre em contato antes da data se a fórmula faltar, se a criança passar a recusá-la ou se não conseguir seguir o plano; não espere perder peso para pedir ajuda."]},"ageMap":{"u3m":"Um teste alterado não confirma o diagnóstico. Mantenha peito ou fórmula habitual enquanto aguarda orientação direta do serviço; se já recebeu um plano específico, siga esse plano.","3a5m":"Leve o registro de mamadas, da fórmula metabólica e do peso às consultas; o volume indicado para um bebê não serve para outro.","6a11m":"Antes de introduzir papinhas, peça à nutricionista exemplos de porções adequadas. Os novos alimentos não substituem automaticamente a fórmula prescrita.","1a":"Combine com quem cuida da criança quais porções oferecer nas refeições da família, sem retirar grupos inteiros por conta própria.","2a5":"Entregue o plano também à creche e combine como lidar com lanches e festas sem pular as refeições prescritas.","6a11":"Ensine a criança a identificar o aspartame nos rótulos e a perguntar antes de aceitar bebidas ou alimentos novos na escola.","12a17":"Combine como manter a fórmula, as coletas e a alimentação fora de casa. Para quem pode engravidar, converse com a equipe antes de uma gestação; se já houver suspeita de gravidez, avise prontamente, pois o controle protege o desenvolvimento do bebê.","unknown":"Informe à equipe a idade e se o registro se refere apenas à triagem ou a um diagnóstico confirmado. A dieta depende do resultado e do crescimento."},"refs":[{"id":"pais20261110_batchN_pps_catalog_a26ea1680821f3d8_1","name":"Protocolo Clínico e Diretrizes Terapêuticas da Fenilcetonúria","url":"https://www.gov.br/conitec/pt-br/midias/protocolos/publicacoes_ms/pcdt_fenilcetonuria_isbn_17-08-2020.pdf/@@display-file/file"},{"id":"pais20261110_batchN_pps_catalog_a26ea1680821f3d8_2","name":"Phenylketonuria (PKU): detailed information","url":"https://www.gov.uk/government/publications/pku-suspected-description-in-brief/phenylketonuria-pku-detailed-information"},{"id":"pais20261110_batchN_pps_catalog_a26ea1680821f3d8_3","name":"Classic Phenylketonuria","url":"https://newbornscreening.hrsa.gov/conditions/classic-phenylketonuria"},{"id":"pais20261110_batchN_pps_catalog_a26ea1680821f3d8_4","name":"Phenylketonuria — PKU Handbook","url":"https://metabolic.ie/wp-content/uploads/2021/08/PKU-Handbook.pdf"}],"aliases":["Fenilcetonúria"],"alwaysUrgent":false,"urgentAges":[],"urgentAcute":false,"resultPath":"references/orientacoes-validadas/parallel-results/OP-20261110N-pps_catalog_a26ea1680821f3d8.json","resultHash":"ce582fcfff21b97c5cad52f1cb513aba92aedb7309ba2e29d95284e1a7b7dda5"},{"jobId":"OP-20261110N-pps_catalog_adac79fdd2be6ecc","ageSections":{},"key":"pps_catalog_adac79fdd2be6ecc","label":"Febre familiar do Mediterrâneo — registro no PPS","specific":true,"entity":"Febre familiar do Mediterrâneo (FMF)","assessment":"{\"classification\":\"VALID_CLINICAL_ENTITY\",\"assessment\":\"Doença autoinflamatória hereditária; não é febre infecciosa adquirida em viagem. Febre recorrente isolada ou ascendência familiar não estabelece o diagnóstico. Não equiparar automaticamente a PFAPA ou outra síndrome periódica.\"}","sections":{"CUIDADOS EM CASA":["Essa doença hereditária pode causar crises de febre com dor na barriga, no peito ou nas articulações. As crises costumam durar poucos dias, e a criança pode ficar bem nos intervalos. A doença em si não é contagiosa.","Para uma crise igual às anteriores, siga o plano combinado com a equipe. Marque o dia de início, a temperatura, onde dói, quanto tempo durou e os remédios usados. Uma criança com essa doença também pode ter uma infecção ou apendicite: não atribua automaticamente um sintoma novo à febre familiar."],"MEDIDAS SEM REMÉDIOS":["Deixe a criança descansar quando sentir dor. Quando estiver bem e conseguir se movimentar sem dor, pode retomar sua rotina. Avise a escola sobre o plano para uma crise e como entrar em contato com a família."],"MEDICAMENTOS":["Se a equipe prescreveu colchicina, mantenha o uso regular, mesmo nos dias sem febre. Ela ajuda a prevenir crises e a proteger os rins; tomar uma dose a mais não corta a crise. Numa crise habitual, mantenha apenas a dose de costume. Não dobre uma dose esquecida.","Antes de começar outro remédio, inclusive antibiótico, avise que a criança usa colchicina. Alguns medicamentos aumentam o risco de intoxicação. Guarde a colchicina fora do alcance das crianças."],"ALIMENTAÇÃO E LÍQUIDOS":["A doença não exige dieta especial. Se estiver alerta e engolindo bem, mantenha a alimentação da idade e ofereça líquidos apropriados à idade conforme a aceitação; para o bebê pequeno, mantenha as mamadas. Não force comida durante a dor."],"VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO":["Vá ao pronto atendimento agora se houver dor abdominal forte que piora, fica localizada ou é diferente das crises conhecidas, especialmente com barriga dura ou vômitos repetidos. Não espere passar só porque outras crises passaram.","Falta de ar, lábios arroxeados, desmaio ou dificuldade para acordar: acione o SAMU 192. Se houver suspeita de ingestão excessiva ou acidental de colchicina, procure ajuda imediatamente, mesmo sem sintomas. Leve a embalagem e não provoque vômito."],"QUANDO REAVALIAR":["Se for a primeira crise, a febre não seguir o padrão combinado ou a criança não melhorar no tempo habitual, procure avaliação no mesmo dia. Os sinais de perigo acima não devem esperar esse prazo.","Mesmo sem crises, mantenha as consultas de reumatologia pediátrica e os exames de sangue e de urina programados. Eles detectam inflamação e sinais precoces de lesão nos rins. Se as crises ficarem frequentes ou surgir diarreia persistente com a colchicina, fale com a equipe antes de mudar o tratamento."]},"ageMap":{"u3m":"Em bebê com menos de três meses, temperatura de 38 °C ou mais exige atendimento imediato. Não espere outra crise ou uma explicação hereditária. Dificuldade para acordar ou para mamar também merece atenção urgente.","3a5m":"Nos primeiros meses pode ser difícil saber onde dói. Febre nova com mamadas ruins ou bebê muito abatido precisa de avaliação; não presuma uma crise familiar. Não substitua as mamadas por água.","6a11m":"Registre se o bebê aceita as mamadas, quantas fraldas molha e se evita mover uma perna durante a febre. Leve o registro à avaliação; procure ajuda mais cedo se estiver muito abatido.","1a":"A criança pode demonstrar dor recusando brincar ou andar. Se tiver febre e de repente não conseguir apoiar uma perna, procure avaliação urgente, mesmo que já tenha tido dores articulares.","2a5":"Peça que a criança mostre onde dói. Se a dor na barriga ficar num ponto, piorar ou não se parecer com as crises habituais, não pressuponha que seja a mesma doença.","6a11":"Combine com a escola quem avisar se houver febre e dor. Peça à criança que mostre no diário quando começou e como a dor afetou as atividades, inclusive entre as crises.","12a17":"Ajude o adolescente a organizar o remédio preventivo sem pular nem duplicar tomadas. Combine uma forma de registrar crises, faltas escolares e limitações para discutir na consulta.","unknown":"Informe a idade, se o diagnóstico já foi confirmado, como são as crises habituais e quais remédios foram prescritos. Diante de sinais de perigo, não espere reunir os dados."},"refs":[{"id":"pais20261110_batchN_pps_catalog_adac79fdd2be6ecc_1","name":"EULAR/PReS endorsed recommendations for the management of familial Mediterranean fever (FMF): 2024 update","url":"https://anzfaid.org/wp-content/uploads/2025/09/FMF-Recommendations-Eular.pdf"},{"id":"pais20261110_batchN_pps_catalog_adac79fdd2be6ecc_2","name":"Febre Familiar do Mediterrâneo (FMF)","url":"https://www.printo.it/pediatric-rheumatology/BR/info/20/Febre-Familiar-do-Mediterr%C3%A2neo-(FMF)"},{"id":"pais20261110_batchN_pps_catalog_adac79fdd2be6ecc_3","name":"Colchicine","url":"https://www.nhs.uk/medicines/colchicine/"},{"id":"pais20261110_batchN_pps_catalog_adac79fdd2be6ecc_4","name":"Fever in under 5s: assessment and initial management","url":"https://www.nice.org.uk/guidance/ng143/chapter/recommendations"}],"aliases":["Febre familiar do Mediterrâneo — apresentação pediátrica aguda","Febre familiar do Mediterrâneo — evolução complicada/refratária","Febre familiar do Mediterrâneo — forma grave/crítica"],"alwaysUrgent":false,"urgentAges":[],"urgentAcute":false,"resultPath":"references/orientacoes-validadas/parallel-results/OP-20261110N-pps_catalog_adac79fdd2be6ecc.json","resultHash":"579ee09897b047c78caeaa9e1bb837ba187626c3a7e0ce39418a51afc4a99c24"}],sources={...base.sources};for(const r of records)for(const s of r.refs)sources[s.id]={name:s.name,url:s.url};const byKey=new Map(records.map(r=>[r.key,r])),norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),byName=new Map(records.map(r=>[norm(r.label),r]));function inherited(fn){const current=root.PaisGuide;root.PaisGuide=base;try{return fn();}finally{root.PaisGuide=current;}}function rowFor(v){return byKey.get(String(v||''))||byName.get(norm(v))||null;}function sectionsFor(row,age){const sections=Object.entries(row.ageSections[age]||row.sections).map(([title,items])=>({title,items:[...items]})),care=sections.find(s=>s.title==='CUIDADOS EM CASA'),note=row.ageMap[age]||row.ageMap.unknown;if(care&&note)care.items.push('Para esta faixa etária: '+note);return sections;}const topics=base.topics.map(t=>{const r=byKey.get(t.key);return r?{...t,generalGuidanceMode:false,catalogOnly:false,specificGuidance:r.specific,termResolution:!r.specific,sections:sectionsFor(r,'unknown'),refs:r.refs.map(s=>s.id),clinicalEntity:r.entity,termAssessment:r.assessment,directedReview:'2026-11-10',urgency:r.alwaysUrgent||t.urgency}:t;});function resolve(v){const r=rowFor(v);return r?topics.find(t=>t.key===r.key):inherited(()=>base.resolve(v));}function build(input={}){const p=input&&typeof input==='object'?input:{},row=rowFor(p.diagnosis)||(()=>{const t=inherited(()=>base.resolve(p.diagnosis));return t&&byKey.get(t.key);})();if(!row)return inherited(()=>base.build(input));const age=p.age===undefined||p.age===null||p.age===''?'unknown':p.age;if(!Object.hasOwn(base.ages,age))return{ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.'};const previous=inherited(()=>base.build({...p,age}));if(!previous?.ok||previous.specificBodyAllowed===false)return previous;if(p.reviewed!==true&&p.danger!=='yes')return{ok:false,code:'REVIEW_REQUIRED',message:'Confirme a avaliação do diagnóstico pela equipe. O site não decide alta.'};const qualifiedAlias=(row.aliases||[]).some(a=>norm(a)===norm(p.diagnosis))&&/grave|critic|complicad|refratari/.test(norm(p.diagnosis));const urgent=row.alwaysUrgent||row.urgentAges.includes(age)||(row.urgentAcute&&(row.aliases||[]).some(a=>norm(a)===norm(p.diagnosis))&&/apresentacao pediatrica aguda/.test(norm(p.diagnosis)))||qualifiedAlias||p.danger==='yes'||previous.mode==='urgent';let sections=sectionsFor(row,age);if(urgent)sections=[{title:'ATENDIMENTO URGENTE',items:['Esta condição exige avaliação presencial urgente. Procure atendimento imediato e não use esta ficha para adiar avaliação.']},...sections];const clean=(v,n)=>typeof v==='string'?v.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,n):'',notes=clean(p.notes,1400),plan=clean(p.returnPlan,200);if(notes)sections.push({title:'COMPLEMENTO DA CONSULTA',items:[notes]});if(plan){const f=sections.find(s=>s.title==='QUANDO REAVALIAR');if(f)f.items.push('Retorno combinado: '+plan);}const text='ORIENTAÇÕES AOS PAIS — '+row.label+'\nFaixa etária: '+base.ages[age]+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>'• '+x).join('\n')).join('\n\n');return{...previous,ok:true,mode:urgent?'urgent':'guidance',topic:row.key,label:row.label,sections,refs:row.refs.map(s=>s.id),text,warnings:urgent?['Avaliação prioritária necessária; esta ficha não autoriza alta.']:[],effectiveAgeBand:age,directedGuidance:true,termResolution:!row.specific,termAssessment:row.assessment};}function audit(){const old=inherited(()=>base.audit()),issues=[...(old.issues||[])];for(const r of records){const t=topics.find(x=>x.key===r.key);if(!t||t.label!==r.label||t.specificGuidance!==r.specific||t.termResolution!==!r.specific||!r.refs.every(s=>sources[s.id]))issues.push('clinical-N-20261110:'+r.key);}return{...old,ok:!issues.length,issues,topics:topics.length};}root.PaisGuide={...base,sources,topics,resolve,build,audit,clinicalN20261110:{keys:records.map(r=>r.key),checked_at:"2026-11-10"}};})(typeof window!=='undefined'?window:globalThis);
